{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "mccode-plugin",
  "version": "1.0.3",
  "description": "Minecraft plugin creation for opencode — Paper/Spigot/Purpur/Folia plugins, Fabric/NeoForge mods, Skript, Bedrock addons, Discord bots. Built on top of opencode.",
  "type": "module",
  "license": "MIT",
  "author": "NOTBOOSTER",
  "repository": {
    "type": "git",
    "url": "https://github.com/NOTBOOSTER/mccode-plugin.git"
  },
  "keywords": ["minecraft", "paper", "spigot", "fabric", "opencode", "plugin", "mccode"],
  "exports": {
    ".": "./src/index.ts",
    "./server": "./src/index.ts",
    "./v2/effect": "./src/index.ts",
    "./v2/promise": "./src/promise.ts"
  },
  "main": "./src/index.ts",
  "files": ["src", "package.json", "README.md", "LICENSE"],
  "homepage": "https://github.com/NOTBOOSTER/mccode-plugin#readme",
  "bugs": {
    "url": "https://github.com/NOTBOOSTER/mccode-plugin/issues"
  },
  "publishConfig": {
    "access": "public"
  },
  "engines": {
    "opencode": ">=1.18.0"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.18.0",
    "effect": "^3.0.0"
  },
  "peerDependencies": {
    "effect": ">=3.0.0"
  }
}

import { define } from "@opencode-ai/plugin/v2/effect"
import { Effect } from "effect"

export const Plugin: any = define({
  id: "mccode",
  effect: Effect.fn(function* (ctx) {
    const PROMPT_MC = yield* Effect.promise(() => Bun.file(new URL("./prompt/mc.txt", import.meta.url)).text())
    const PROMPT_NEW = yield* Effect.promise(() => Bun.file(new URL("./command/new.txt", import.meta.url)).text())
    const PROMPT_MCSTATUS = yield* Effect.promise(() => Bun.file(new URL("./command/mcstatus.txt", import.meta.url)).text())
    yield* ctx.agent.transform((draft) => {
      draft.update("minecraft", (agent) => {
        agent.description =
          "Minecraft development plugin — Tab to select minecraft. Interviews you (platform, version, build tool, dependencies), verifies versions online, plans under plans/, then builds Paper/Spigot/Purpur/Folia plugins, Fabric/NeoForge mods, Skript, Bedrock addons or Discord bots."
        agent.mode = "all"
        agent.prompt = PROMPT_MC
        agent.hidden = false
      })
    })
    yield* ctx.command.transform((draft) => {
      draft.remove("new")
      draft.update("mcnew", (cmd) => {
        cmd.description = "Start a new Minecraft project — interviews, verifies versions, then plans and builds"
        cmd.agent = "minecraft"
        cmd.template = PROMPT_NEW
      })
      draft.update("mcstatus", (cmd) => {
        cmd.description = "Report Minecraft plan progress under plans/"
        cmd.agent = "minecraft"
        cmd.template = PROMPT_MCSTATUS
      })
    })
  }),
})
// Legacy server for old opencode loader — same via config
Plugin.server = async () => {
  const PROMPT_MC = await Bun.file(new URL("./prompt/mc.txt", import.meta.url)).text()
  const PROMPT_NEW = await Bun.file(new URL("./command/new.txt", import.meta.url)).text()
  const PROMPT_MCSTATUS = await Bun.file(new URL("./command/mcstatus.txt", import.meta.url)).text()
  return {
    config: async (config: any) => {
      if (!config.agent) config.agent = {}
      config.agent["minecraft"] = {
        description:
          "Minecraft development plugin — Tab to select minecraft. Interviews you (platform, version, build tool, dependencies), verifies versions online, plans under plans/, then builds Paper/Spigot/Purpur/Folia plugins, Fabric/NeoForge mods, Skript, Bedrock addons or Discord bots.",
        mode: "all",
        prompt: PROMPT_MC,
        hidden: false,
      }
      if (!config.command) config.command = {}
      delete config.command["new"]
      config.command["mcnew"] = {
        description: "Start a new Minecraft project — interviews, verifies versions, then plans and builds",
        agent: "minecraft",
        template: PROMPT_NEW,
      }
      config.command["mcstatus"] = {
        description: "Report Minecraft plan progress under plans/",
        agent: "minecraft",
        template: PROMPT_MCSTATUS,
      }
    },
  }
}
export default Plugin
